    # Boolean logic example
    # if (Shooter_will_make_the_shot == True):
    #     shoot

    # ========================================================================

    # Probability logic example
    # if (Probability_we_make_the_shot >= 80%)
    #     shoot

    # ========================================================================

    import pandas as pd
    import random

    # Set seed for reproducibility
    random.seed(42)

    # Likelihoods
    likelihoods = {
        'green': {'A': 36/40, 'B': 20/40},
        'red':   {'A': 4/40,  'B': 20/40}
    }

    def calculate_bayesian_sequence(draws):
        """Calculate P(Box B) after each draw"""
        prior_A = 0.5
        prior_B = 0.5
    
        results = [('Initial', '-', 50.0)]
    
        for i, color in enumerate(draws, 1):
            like_A = likelihoods[color]['A']
            like_B = likelihoods[color]['B']
        
            total = like_A * prior_A + like_B * prior_B
        
            prior_A = (like_A * prior_A) / total
            prior_B = (like_B * prior_B) / total
        
            results.append((f'Draw {i}', color.capitalize(), round(prior_B * 100, 1)))
    
        return results

    # Generate 3 different sequences
    sequences = {
        'Sequence 1': ['red', 'red', 'green', 'red', 'green'],
        'Sequence 2': ['green', 'green', 'green', 'red', 'green'],
        'Sequence 3': ['red', 'green', 'red', 'red', 'green']
    }

    # Create data for table
    all_data = []
    for seq_name, draws in sequences.items():
        results = calculate_bayesian_sequence(draws)
        for step, color, prob in results:
            all_data.append({
                'Sequence': seq_name,
                'Step': step,
                'Bead Color': color,
                'P(Box B) %': prob
            })

    df = pd.DataFrame(all_data)

    # Pivot to show sequences side by side
    pivot = df.pivot(index=['Step', 'Bead Color'], columns='Sequence', values='P(Box B) %')
    pivot = pivot.reset_index()

    # Display with nice formatting
    pivot.style.set_properties(**{
        'text-align': 'center',
        'font-size': '16pt'
    }).set_table_styles([
        {'selector': 'th', 'props': [('font-size', '18pt'), ('text-align', 'center'), ('background-color', '#2c3e50'), ('color', 'white')]},
        {'selector': 'td', 'props': [('text-align', 'center')]}
    ])

    # ========================================================================



    return None


